        options: [{ id: 'a', text: '계산 오류' }, { id: 'b', text: '사이클 정점에서 이익이 최대 → PER이 최저로 보여 매수 신호처럼 오인' }, { id: 'c', text: '거래량 감소' }, { id: 'd', text: '세금' }],
