// ── New Duolingo-style types ──
export type LessonType = 'learn' | 'quiz' | 'fillblank' | 'matching';
export type CategoryId = 'vocabulary' | 'newsLearning' | 'chartAnalysis' | 'companyAnalysis' | 'psychology' | 'macro' | 'portfolio' | 'quant';

export interface LearnLesson {
  type: 'learn';
  emoji: string;
  title: string;
  content: string;
}

export interface QuizLesson {
  type: 'quiz';
  question: string;
  options: string[];
  answer: number;
  explanation: string;
}

export interface FillBlankLesson {
  type: 'fillblank';
  question: string;
  answer: string;
  options: string[];
  explanation: string;
}

export interface MatchingLesson {
  type: 'matching';
  question: string;
  pairs: { term: string; definition: string }[];
}

export type DuoLesson = LearnLesson | QuizLesson | FillBlankLesson | MatchingLesson;

export interface DuoLevel {
  id: string;
  title: string;
  lessons: DuoLesson[];
}

export interface DuoCategory {
  id: CategoryId;
  title: string;
  emoji: string;
  color: [string, string];
  levels: DuoLevel[];
}

